#include <iostream>
#include <vector>
#include <memory>
#include <utility>

#include "SpreadSheetCell.h"
#include "DoubleSpreadsheet.h"
#include "StringSpreadsheet.h"

using namespace std;


int main(){

    vector<unique_ptr<SpreadSheetCell>> Excel ;


    unique_ptr<SpreadSheetCell> cell = make_unique<StringSpreadsheet>();
    unique_ptr<SpreadSheetCell> cell1 = make_unique<DoubleSpreadsheet>();
    unique_ptr<SpreadSheetCell> cell2 = make_unique<DoubleSpreadsheet>();


    cell->set("");
    cell1->set(18.1);
    cell2->set(12.1);

    Excel.push_back(std::move(cell));//move(cell)
     Excel.push_back(std::move(cell1));
    Excel.push_back(std::move(cell2));


    cout<<"Vector: [";

    for(const unique_ptr<SpreadSheetCell> & cell : Excel){
        cout<< cell->getString() << ", ";
    }
    cout<<"]";

    return 0;
}

#include "SpreadSheetCell.h"
#include <optional>
#include <format>
#include <string>
#include <string_view>

using namespace std;


class DoubleSpreadsheet : public SpreadSheetCell
{
    private:

    optional<double> data;

    public:


    void set(double value){

        data = value;
    }

    void set(std::string_view value) override{
        data = stringToDouble(value);
    }

    std::string getString() const override{

        return doubleToString(data.value_or(nullopt));
    }
    string doubleToString(double value)const
    {

       return to_string(value);
    }
    double stringToDouble(string_view value) const
    {
        optional<string_view> val =value ;

        if(!val.has_value())
            return 0;


        return stod(string( val.value() ));
    }

};
